Q: Is it possible to replace table cells with other elements using display: table-cell? A: <p>From what I understand of your question,<br />
Are you looking for something like that ?</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const 
  myTable   = document.querySelector('#my-table')
, lnkPrefix = 'https://stackoverflow.com/'
  ;
myTable.addEventListener('click', ({target: td_clicked}) =&gt;
  {
  if (!td_clicked.matches('td[data-lnk]')) return; // ignore them

  window.location.replace(`${lnkPrefix}${td_clicked.dataset.lnk}`);
  // window.open(`${lnkPrefix}${td_clicked.dataset.lnk}`, '_blank').focus();
  })</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>td 
  {
  border  : 1px solid lightgrey;
  width   : 10em;
  padding : 0 1em;
  }
td[data-lnk] 
  {
  background : lightblue;
  cursor     : pointer;
  }
td[data-lnk]:hover
  {
  color        : red;
  border-color : black;
  }</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;table id="my-table"&gt;
  &lt;tr&gt; 
    &lt;td data-lnk="questions/1687296/"&gt; event delgation &lt;/td&gt;
    &lt;td&gt; no link... &lt;/td&gt;
    &lt;td data-lnk="questions/72742668"&gt; data attribute styling &lt;/td&gt;
  &lt;/tr&gt;
  &lt;tr&gt;
    &lt;td&gt; xxx &lt;/td&gt;
    &lt;td data-lnk="help/how-to-ask" &gt; how to ask... &lt;/td&gt;
    &lt;td&gt; yyy &lt;/td&gt;
  &lt;/tr&gt;
&lt;/table&gt;</code></pre>
</div>
</div>
